//! Offline PCM16 WAV processing. No realtime DSP or external codecs.
use std::{fs,path::Path};
#[derive(Clone,Copy,Debug,PartialEq,serde::Serialize,serde::Deserialize)] #[serde(default)] pub struct WavEffects{pub low_db:f32,pub high_db:f32,pub room:f32}
impl Default for WavEffects{fn default()->Self{Self{low_db:0.,high_db:0.,room:0.}}}
fn u16_at(b:&[u8],i:usize)->u16{u16::from_le_bytes([b[i],b[i+1]])}
fn u32_at(b:&[u8],i:usize)->u32{u32::from_le_bytes([b[i],b[i+1],b[i+2],b[i+3]])}
/// Two-band crossover at 1 kHz plus three decaying early-reflection taps.
pub fn process_pcm16_wav(input:&[u8],fx:WavEffects)->Result<Vec<u8>,String>{
 if input.len()<12||input.len()>32*1024*1024||&input[..4]!=b"RIFF"||&input[8..12]!=b"WAVE"{return Err("Expected PCM16 RIFF WAV, max 32 MiB".into());}
 let mut fmt=None;let mut data=None;let mut at=12;while at+8<=input.len(){let len=u32_at(input,at+4) as usize;let start=at+8;let end=start.checked_add(len).ok_or("Invalid WAV chunk")?;if end>input.len(){return Err("Truncated WAV chunk".into());}match &input[at..at+4]{b"fmt " if len>=16=>fmt=Some(&input[start..end]),b"data"=>data=Some(start..end),_=>{}}at=end+(len&1);}
 let fmt=fmt.ok_or("Missing WAV format")?;let data=data.ok_or("Missing WAV data")?;let channels=u16_at(fmt,2) as usize;let rate=u32_at(fmt,4) as usize;if u16_at(fmt,0)!=1||!(1..=2).contains(&channels)||u16_at(fmt,14)!=16||u16_at(fmt,12) as usize!=2*channels||!(8000..=96000).contains(&rate)||data.len()%(2*channels)!=0{return Err("Only mono/stereo PCM16 WAV, 8–96 kHz".into());}
 if ![fx.low_db,fx.high_db,fx.room].iter().all(|v|v.is_finite()){return Err("Invalid effects parameters".into());}let mut out=input.to_vec();let low=10_f32.powf(fx.low_db.clamp(-12.,12.)/20.);let high=10_f32.powf(fx.high_db.clamp(-12.,12.)/20.);let room=fx.room.clamp(0.,1.);let coeff=1.-(-std::f32::consts::TAU*1000./rate as f32).exp();let samples:Vec<f32>=input[data.clone()].chunks_exact(2).map(|x|i16::from_le_bytes([x[0],x[1]]) as f32/32768.).collect();let mut filter=[0.;2];let mut dry=vec![0.;samples.len()];for (i,&x) in samples.iter().enumerate(){let c=i%channels;filter[c]+=coeff*(x-filter[c]);dry[i]=low*filter[c]+high*(x-filter[c]);}
 let taps=[(rate*37/1000*channels,0.24_f32),(rate*73/1000*channels,0.15_f32),(rate*113/1000*channels,0.09_f32)];for i in 0..dry.len(){let mut y=dry[i];for (delay,gain) in taps{if i>=delay{y+=room*gain*dry[i-delay];}}let v=(y*32768.).round().clamp(-32768.,32767.) as i16;let j=data.start+i*2;out[j..j+2].copy_from_slice(&v.to_le_bytes());}Ok(out)
}
pub fn render_wav_effects(source:&Path,root:&Path,fx:WavEffects)->Result<String,String>{let size=fs::metadata(source).map_err(|e|e.to_string())?.len();if size>32*1024*1024{return Err("WAV max 32 MiB".into());}let input=fs::read(source).map_err(|e|e.to_string())?;let output=process_pcm16_wav(&input,fx)?;let rel=format!("assets/fx-{}.wav",uuid::Uuid::new_v4());fs::create_dir_all(root.join("assets")).map_err(|e|e.to_string())?;fs::write(root.join(&rel),output).map_err(|e|e.to_string())?;Ok(rel)}
#[cfg(test)]mod tests{use super::*;#[test]fn rejects_invalid(){assert!(process_pcm16_wav(b"bad",Default::default()).is_err());}#[test]fn unity_preserves_samples(){let mut b=b"RIFF".to_vec();b.extend_from_slice(&40u32.to_le_bytes());b.extend_from_slice(b"WAVEfmt ");b.extend_from_slice(&16u32.to_le_bytes());b.extend_from_slice(&1u16.to_le_bytes());b.extend_from_slice(&1u16.to_le_bytes());b.extend_from_slice(&8000u32.to_le_bytes());b.extend_from_slice(&16000u32.to_le_bytes());b.extend_from_slice(&2u16.to_le_bytes());b.extend_from_slice(&16u16.to_le_bytes());b.extend_from_slice(b"data");b.extend_from_slice(&4u32.to_le_bytes());b.extend_from_slice(&1234i16.to_le_bytes());b.extend_from_slice(&(-1000i16).to_le_bytes());assert_eq!(process_pcm16_wav(&b,Default::default()).unwrap(),b);}}

/// Stateful streaming DSP core. Allocate once at construction; process arbitrary interleaved blocks
/// with the same history. This is not yet attached to Bevy's audio callback.
pub struct StreamingEffects{channels:usize,coeff:f32,low:[f32;2],history:Vec<f32>,cursor:usize,channel:usize,taps:[usize;3],gain_low:f32,gain_high:f32,room:f32}
impl StreamingEffects{
 pub fn new(rate:u32,channels:usize,fx:WavEffects)->Result<Self,String>{if !(8000..=96000).contains(&rate)||!(1..=2).contains(&channels){return Err("Unsupported DSP format".into());}let taps=[37,73,113].map(|ms|rate as usize*ms/1000*channels);let mut s=Self{channels,coeff:1.-(-std::f32::consts::TAU*1000./rate as f32).exp(),low:[0.;2],history:vec![0.;taps[2]+channels],cursor:0,channel:0,taps,gain_low:1.,gain_high:1.,room:0.};s.set_effects(fx)?;Ok(s)}
 pub fn set_effects(&mut self,fx:WavEffects)->Result<(),String>{if ![fx.low_db,fx.high_db,fx.room].iter().all(|v|v.is_finite()){return Err("Invalid DSP settings".into());}self.gain_low=10_f32.powf(fx.low_db.clamp(-12.,12.)/20.);self.gain_high=10_f32.powf(fx.high_db.clamp(-12.,12.)/20.);self.room=fx.room.clamp(0.,1.);Ok(())}
 pub fn process(&mut self,samples:&mut [f32]){let n=self.history.len();for x in samples{let input=if x.is_finite(){*x}else{0.};let c=self.channel;self.low[c]+=self.coeff*(input-self.low[c]);let dry=if self.gain_low==1.&&self.gain_high==1.{input}else{self.gain_low*self.low[c]+self.gain_high*(input-self.low[c])};let mut out=dry;for (delay,gain) in self.taps.into_iter().zip([0.24,0.15,0.09]){out+=self.room*gain*self.history[(self.cursor+n-delay)%n];}self.history[self.cursor]=dry+self.room*0.35*self.history[(self.cursor+n-self.taps[2])%n];self.cursor=(self.cursor+1)%n;self.channel=(c+1)%self.channels;*x=out.clamp(-1.,1.);}}
}
#[cfg(test)]mod streaming_tests{use super::*;#[test]fn chunk_continuity_and_stereo(){let fx=WavEffects{low_db:2.,high_db:-1.,room:0.7};let mut a=vec![0.;2400];a[0]=0.5;let mut b=a.clone();let mut one=StreamingEffects::new(8000,2,fx).unwrap();let mut split=StreamingEffects::new(8000,2,fx).unwrap();one.process(&mut a);for c in b.chunks_mut(137){split.process(c);}assert_eq!(a,b);assert!(a.iter().skip(1).step_by(2).all(|v|*v==0.));assert!(a[592].abs()>0.001);}}
